class C { n = 1; bump(): number { this.n += 1; return this.n; } }
async function main(): Promise<void> {
  const c = new C();
  const o: any = { inner: c };
  console.log(typeof o.inner.bump);
  console.log(o.inner.n);
  c.n = 5;
  console.log(o.inner.n);
  console.log(o.inner.bump(), c.n);
  const l: any = [c];
  console.log(l[0].n, typeof l[0].bump);
}
